func:
var instructionMsg = '**CRITICAL**: Please review task ' + msg.task.id + ' and provide your feedback using the `build review` command.\n\n' +
    'The syntax is:\n' +
    'build review ' + msg.task.id + ' <approve|reject> "<reasoning>"\n\n' +
    'RULES:\n' +
    '1. Your reasoning MUST be a single line of text.\n' +
    '2. Enclose your reasoning in double quotes (").\n' +
    '3. DO NOT use double quotes inside your reasoning string (use single quotes instead).\n' +
    '4. DO NOT ask questions; provide ONLY the final review via the bash tool.';

msg.payload = "build task update --id " + msg.task.id + " --agent-id 4 --comment-author-id 1 --comment \"" + instructionMsg.replace(/"/g, "'") + "\" --audit-action assign_to_boss";
return msg;

var errorMsg = 'Tests failed:\n' + msg.payload;
msg.payload = "build task update --id " + msg.task.id + " --inc-approval-attempts --comment-author-id 3 --comment \"" + errorMsg.replace(/"/g, "'") + "\"";
return msg;

var stdout = (msg.payload || '').trim();
try {
    var res = JSON.parse(stdout);
    var taskObj = Array.isArray(res) ? res[0] : res;
    var attempts = taskObj.approval_attempts;
    var lead_interventions = taskObj.lead_interventions;

    if (attempts >= 3) {
        if (lead_interventions < 3) {
            msg.payload = "build task update --id " + msg.task.id + " --status stuck --agent-id 5 --reset-approval-attempts --inc-lead-interventions --audit-action escalate_to_lead";
        } else {
            msg.payload = "build task update --id " + msg.task.id + " --status failed --agent-id 1 --audit-action task_rejected";
        }
    } else {
        msg.payload = "build task update --id " + msg.task.id + " --agent-id 2 --audit-action assign_to_dev";
    }
} catch (e) {
    node.error('Error parsing attempts JSON: ' + e.message);
    msg.payload = "build task update --id " + msg.task.id + " --agent-id 2";
}
return msg;
